inline constexpr CellFont emoji12x24 = {12, 24, 80, emoji12x24Codepoints, emoji12x24Bitmaps};

// The emoji halves sized for f, or nullptr.
inline const CellFont* emojiCellsFor(const CellFont& f) {
  if (f.w == 6 && f.h == 12) return &emoji6x12;
  if (f.w == 8 && f.h == 14) return &emoji8x14;
  if (f.w == 8 && f.h == 16) return &emoji8x16;
  if (f.w == 10 && f.h == 18) return &emoji10x18;
  if (f.w == 12 && f.h == 24) return &emoji12x24;
  return nullptr;
}

// The bitmap for cp in font f: tray emoji halves from the matching emoji
// table, everything else through glyphFor.
inline const uint8_t* cellGlyph(const CellFont& f, char32_t cp) {
  if (emojiIndex(cp) >= 0 || isWideTail(cp))
    if (const CellFont* e = emojiCellsFor(f))
      if (const uint8_t* g = findGlyph(*e, cp)) return g;
  return glyphFor(f, cp);
}

